const ZIGZAG_BUILD_ID='ZIGZAG-0.7-ZIGGY-ZORRITO-20261031';
import React,{useEffect,useState} from 'react';import{createRoot}from'react-dom/client';import{House,CalendarDays,BookOpen,UserRound,Rocket,Target,Map,Heart,RotateCcw,Lightbulb,Plus,Trash2,Clock,AlertCircle,ChevronLeft,Check,Settings,Brain,Undo2,Bell,ArrowRight,Play,Pause,Save,Eye,EyeOff,Volume2,VolumeX,Square}from'lucide-react';import './style.css';
type Task={id:string;name:string;date:string;time:string;duration:number|null;status:'pending'|'active'|'paused'|'done';resume:string;reminder:number};type Spark={id:string;text:string;category?:'idea'|'pendiente'|'pregunta'|'inspiracion';created?:string};type Prefs={start:string;focus:string;energy:string;support:string;changes:string;estimate:string;lowStim:boolean};type State={tasks:Task[];sparks:Spark[];resources:string[];prefs:Prefs};
const initial:State={tasks:[],sparks:[],resources:[],prefs:{start:'tiny',focus:'untimed',energy:'ask',support:'balanced',changes:'preview',estimate:'request',lowStim:false}};const uid=()=>Math.random().toString(36).slice(2,10);const localDate=(d:Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const today=()=>localDate(new Date());const shiftDate=(value:string,days:number)=>{const d=new Date(value+'T12:00:00');d.setDate(d.getDate()+days);return localDate(d)};const mins=(s:string)=>{const [h,m]=s.split(':').map(Number);return h*60+m};const fmt=(n:number)=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
function App(){const[data,setData]=useState<State>(()=>{try{return {...initial,...JSON.parse(localStorage.getItem('zigzag-v1')||'{}')}}catch{return initial}});const[tab,setTab]=useState('Inicio');const[page,setPage]=useState('');const[view,setView]=useState<'cards'|'timeline'>(()=>localStorage.getItem('zigzag-view')==='timeline'?'timeline':'cards');const[date,setDate]=useState(today());const[name,setName]=useState('');const[time,setTime]=useState('');const[duration,setDuration]=useState('30');const[resume,setResume]=useState('');const[editing,setEditing]=useState<string|null>(null);const[notice,setNotice]=useState('');const[expand,setExpand]=useState(false);const[planIds,setPlanIds]=useState<string[]>([]);const[undo,setUndo]=useState<Task[]|null>(null);const[flowId,setFlowId]=useState('');const[flowStep,setFlowStep]=useState('');const[starterId,setStarterId]=useState('');const[starterStep,setStarterStep]=useState('');const[focusNote,setFocusNote]=useState('');const[focusId,setFocusId]=useState('');const[focusRunning,setFocusRunning]=useState(false);const[focusSeconds,setFocusSeconds]=useState(0);const[focusGoal,setFocusGoal]=useState<0|120|300|600>(0);const[focusBreak,setFocusBreak]=useState(false);const[focusGuide,setFocusGuide]=useState(false);const[focusGuideChecks,setFocusGuideChecks]=useState<boolean[]>([false,false,false]);const[spark,setSpark]=useState('');const[sparkCategory,setSparkCategory]=useState<'idea'|'pendiente'|'pregunta'|'inspiracion'>('idea');const[sparkSearch,setSparkSearch]=useState('');const[mapFilter,setMapFilter]=useState<'all'|'pending'|'active'|'done'>('all');const[resetStep,setResetStep]=useState<'choose'|'pause'|'orient'>('choose');const[resource,setResource]=useState('');const[estimateId,setEstimateId]=useState('');const[estimateVal,setEstimateVal]=useState(30);const[conflictId,setConflictId]=useState('');const[conflictTime,setConflictTime]=useState('');const[resetMode,setResetMode]=useState(false);
useEffect(()=>localStorage.setItem('zigzag-v1',JSON.stringify(data)),[data]);useEffect(()=>localStorage.setItem('zigzag-view',view),[view]);useEffect(()=>{if(!focusRunning)return;const t=setInterval(()=>setFocusSeconds(x=>x+1),1000);return()=>clearInterval(t)},[focusRunning]);const tasks=data.tasks;const day=tasks.filter(t=>t.date===date&&t.status!=='done');const completedToday=tasks.filter(t=>t.date===date&&t.status==='done');const allToday=tasks.filter(t=>t.date===date);const fixed=day.filter(t=>t.time).sort((a,b)=>mins(a.time)-mins(b.time));const flexible=day.filter(t=>!t.time);const active=tasks.find(t=>t.status==='active'||t.status==='paused');const resumable=tasks.filter(t=>t.status==='active'||t.status==='paused'||Boolean(t.resume.trim())).filter(t=>t.status!=='done').sort((a,b)=>(a.status==='active'?-2:a.status==='paused'?-1:0)-(b.status==='active'?-2:b.status==='paused'?-1:0));const ziggyQuiet=data.prefs.support==='minimal';const ziggyStartTip=data.prefs.start==='prepare'?'Puedes preparar tu espacio antes de empezar.':data.prefs.start==='choose'?'Puedes mirar opciones y elegir una, sin obligación.':'Podemos buscar un paso pequeño y suficiente.';const ziggyEnergyTip=data.prefs.energy==='quiet'?'No cambiaré tu plan sin que me lo pidas.':data.prefs.energy==='simple'?'Podemos hacer una versión más liviana.':'¿Qué necesitas ahora?';const conflicts=fixed.flatMap((a,i)=>fixed.slice(i+1).filter(b=>mins(a.time)<mins(b.time)+(b.duration||30)&&mins(b.time)<mins(a.time)+(a.duration||30)).map(b=>[a,b]));const update=(id:string,patch:Partial<Task>)=>setData(d=>({...d,tasks:d.tasks.map(t=>t.id===id?{...t,...patch}:t)}));const pref=(key:keyof Prefs,value:string|boolean)=>setData(d=>({...d,prefs:{...d.prefs,[key]:value}}));const open=(p:string)=>{setPage(p);setNotice('');setResetMode(false);setResetStep('choose')};const addTask=()=>{if(!name.trim())return setNotice('Escribe el nombre de la actividad.');if(time&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(time))return setNotice('La hora debe tener formato HH:MM.');const n=Number(duration);if(!Number.isInteger(n)||n<5||n>480)return setNotice('La duración debe ser entre 5 y 480 minutos.');if(time&&mins(time)+n>1440)return setNotice('El compromiso debe terminar dentro del día.');const previous=tasks.find(t=>t.id===editing);const obj:Task={id:editing||uid(),name:name.trim(),date,time,duration:n,status:previous?.status||'pending',resume:resume.trim(),reminder:previous?.reminder||0};setData(d=>({...d,tasks:editing?d.tasks.map(t=>t.id===editing?obj:t):[...d.tasks,obj]}));setEditing(null);setName('');setTime('');setDuration('30');setResume('');open('');setNotice('Guardado en este dispositivo.')};const editTask=(t:Task)=>{setEditing(t.id);setName(t.name);setDate(t.date);setTime(t.time);setDuration(String(t.duration||30));setResume(t.resume);open('task')};const goTab=(t:string)=>{setTab(t);setStarterId('');open('')};const saveEstimate=()=>{update(estimateId,{duration:estimateVal});open('');setNotice('Estimación guardada. No se asignó ningún horario.')};const startPlan=()=>{setPlanIds(flexible.map(t=>t.id));open('plan')};const applyPlan=()=>{setUndo(tasks);const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+1);const next=localDate(d);setData(x=>({...x,tasks:x.tasks.map(t=>planIds.includes(t.id)?{...t,date:next}:t)}));open('');setNotice('Cambios aplicados. Puedes deshacerlos.')};const openFlow=(id:string)=>{setFlowId(id);setFlowStep(tasks.find(t=>t.id===id)?.resume||'');open('camino')};const startFocus=(id:string)=>{setFocusId(id);setFocusSeconds(0);setFocusGoal(0);setFocusBreak(false);setFocusGuide(false);setFocusGuideChecks([false,false,false]);setFocusRunning(true);setFocusNote(tasks.find(t=>t.id===id)?.resume||'');update(id,{status:'active'});open('focusSession')};const [ziggyOpen,setZiggyOpen]=useState(false);const [aiMessages,setAiMessages]=useState<Array<{role:'user'|'assistant';content:string}>>([]);const [aiInput,setAiInput]=useState('');const [aiBusy,setAiBusy]=useState(false);const [aiError,setAiError]=useState('');const [aiEnabled,setAiEnabled]=useState(false);const [memoryEnabled,setMemoryEnabled]=useState(()=>localStorage.getItem('zigzag-ai-memory-enabled')==='yes');const [memoryNote,setMemoryNote]=useState(()=>localStorage.getItem('zigzag-ai-memory-note')||'');const [memoryEditor,setMemoryEditor]=useState(false);const [unblockMode,setUnblockMode]=useState<'inicio'|'saturacion'|'energia'|'distraccion'|null>(null);const [unblockTask,setUnblockTask]=useState('');const aiAbort=React.useRef<AbortController|null>(null);
const askAboutTask=(task:Task,kind:'iniciar'|'dividir'|'simplificar')=>{
 const prompt=kind==='iniciar'?'Ayúdame a empezar esta actividad con un primer paso de menos de dos minutos.':kind==='dividir'?'Divide esta actividad en tres a cinco pasos pequeños y concretos, sin imponer horarios.':'Ayúdame a simplificar esta actividad para un día de poca energía; incluye la opción de posponerla o descansar.';
 setAiInput(`${prompt}\nActividad que elegí compartir: ${task.name.slice(0,120)}${task.resume?'\nNota: '+task.resume.slice(0,180):''}\nNo modifiques mi agenda sin preguntarme.`);
 setAiError('');
 setZiggyOpen(true);
};

const [suggestedSteps,setSuggestedSteps]=useState<Array<{id:string;text:string;selected:boolean}>>([]);
const [stepFeedback,setStepFeedback]=useState('');
const makeSteps=()=>{
 const last=[...aiMessages].reverse().find(m=>m.role==='assistant')?.content||'';
 if(!last){setStepFeedback('Primero conversa con Ziggy para preparar tus pasos.');return}
 const lines=last.split(/\n+/).map(x=>x.trim()).filter(Boolean);
 const candidates=lines.map(x=>x.replace(/^(?:[-*•]|\d+[.)])\s*/, '').replace(/^\*\*(.+)\*\*$/,'$1').trim())
  .filter(x=>x.length>=8&&x.length<=150&&!/^hola|^claro|^puedes contarme/i.test(x));
 const steps=(candidates.length>=2?candidates.slice(0,6):[last.slice(0,140)]).map(text=>({id:uid(),text,selected:true}));
 setSuggestedSteps(steps);setStepFeedback('Revisa y edita los pasos. Solo se guardarán los que elijas.');
};
const saveSteps=()=>{
 const chosen=suggestedSteps.filter(s=>s.selected&&s.text.trim());
 if(!chosen.length){setStepFeedback('Elige al menos un paso para guardarlo.');return}
 setData(d=>({...d,tasks:[...d.tasks,...chosen.map(s=>({id:uid(),name:s.text.trim().slice(0,120),date:today(),time:'',duration:5,status:'pending' as const,resume:'Sugerido por Ziggy · puedes cambiarlo cuando quieras',reminder:0}))]}));
 setSuggestedSteps([]);setStepFeedback(`${chosen.length} paso(s) guardado(s) en Mi Día. Puedes modificarlos o eliminarlos.`);
};

useEffect(()=>{localStorage.setItem('zigzag-ai-memory-enabled',memoryEnabled?'yes':'no')},[memoryEnabled]);useEffect(()=>{if(memoryEnabled)localStorage.setItem('zigzag-ai-memory-note',memoryNote.slice(0,500))},[memoryNote,memoryEnabled]);
const askZiggy=async()=>{const message=aiInput.trim();if(!message||aiBusy)return;const next=[...aiMessages,{role:'user' as const,content:message}].slice(-10);setAiMessages(next);setAiInput('');setAiError('');setAiBusy(true);const controller=new AbortController();aiAbort.current=controller;try{const response=await fetch('https://www.academiaconecta360.cl/zigzag-api/chat.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:next,...(memoryEnabled&&memoryNote.trim()?{memory:memoryNote.trim().slice(0,500)}:{})}),signal:controller.signal});const payload=await response.json();if(!response.ok||typeof payload.reply!=='string')throw new Error(payload.error||'Ziggy no pudo responder ahora.');setAiMessages(prev=>[...prev,{role:'assistant' as const,content:payload.reply}].slice(-10));setAiEnabled(true)}catch(e){if(!controller.signal.aborted)setAiError(e instanceof Error?e.message:'No hay conexión. Puedes seguir usando ZIGZAG sin IA.')}finally{setAiBusy(false);aiAbort.current=null}};
const [ziggyFeeling,setZiggyFeeling]=useState<'saturada'|'dispersa'|'bloqueada'|'bien'|''>('');const ziggyText=ziggyFeeling==='saturada'?`No tienes que resolver todo ahora. ${ziggyEnergyTip} Reset está disponible si te sirve.`:ziggyFeeling==='dispersa'?'Podemos dejar una idea en Chispas para que no tengas que sostenerla en la cabeza.':ziggyFeeling==='bloqueada'?ziggyStartTip:ziggyFeeling==='bien'?'Qué bueno. También puedes descansar o explorar sin exigirte nada.':active?`«${active.name}» sigue disponible para retomar, sin perder tu punto de regreso.`:conflicts.length?'RADAR encontró horarios que se cruzan. Puedes revisarlos sin mover nada automáticamente.':day.length?'Hay actividades en tu día. Tú decides si quieres verlas.':'Estoy aquí si me necesitas. No tienes que hacer nada ahora.';const ziggyAction=()=>{const feeling=ziggyFeeling;if(feeling==='saturada'){setResetMode(true);setZiggyOpen(false)}else if(feeling==='dispersa'){open('chispas');setZiggyOpen(false)}else if(feeling==='bloqueada'){open('arranque');setZiggyOpen(false)}else if(active){open('vuelve');setZiggyOpen(false)}else{goTab('Mi día');setZiggyOpen(false)}};const sections=[['start','Así arranco','rocket'],['focus','Así me concentro','target'],['energy','Así funciona mi energía','heart'],['support','Así necesito apoyo','brain'],['changes','Así manejo los cambios','rotate'],['resources','Mis superrecursos','spark']];const configs:Record<string,{key:keyof Prefs;label:string;options:[string,string][]}>={start:{key:'start',label:'Cuando me cuesta empezar…',options:[['tiny','Un paso muy pequeño'],['prepare','Preparar el espacio primero'],['choose','Ver varias opciones']]},focus:{key:'focus',label:'Para concentrarme prefiero…',options:[['untimed','Sin temporizador'],['visible','Ver el tiempo transcurrido'],['sessions','Elegir duración de sesión']]},energy:{key:'energy',label:'Cuando cambia mi energía…',options:[['ask','Pregúntame qué necesito'],['simple','Ofrece una versión liviana'],['quiet','No sugieras cambios']]},support:{key:'support',label:'La presencia de Ziggy…',options:[['balanced','Equilibrada y contextual'],['minimal','Mínima, solo si lo llamo'],['active','Más sugerencias discretas']]},changes:{key:'changes',label:'Cuando cambia el plan…',options:[['preview','Ver alternativas antes de decidir'],['manual','Reorganizar manualmente'],['steps','Un cambio a la vez']]},estimate:{key:'estimate',label:'Tiempo Realista…',options:[['request','Solo cuando lo solicito'],['offer','Sugerencias discretas'],['off','Sin sugerencias de duración']]}};const renderIcon=(id:string)=>id==='start'?<Rocket/>:id==='focus'?<Target/>:id==='energy'?<Heart/>:id==='support'?<Brain/>:id==='changes'?<RotateCcw/>:<Lightbulb/>;
return <div className={data.prefs.lowStim?'app low-stim':'app'}><header><button className="brand" onClick={()=>goTab('Inicio')} aria-label="Zigzag, ir a Inicio">zigzag<span>.</span><small>tu ritmo cuenta</small></button><div className="header-actions"><button className="share-app" onClick={async()=>{const url=window.location.href;try{if(navigator.share){await navigator.share({title:'ZIGZAG con Ziggy',text:'Conoce ZIGZAG, tu espacio para organizarte a tu ritmo.',url})}else if(navigator.clipboard){await navigator.clipboard.writeText(url);setNotice('Enlace copiado. Compártelo con quien quieras.')}else{setNotice('Copia la dirección del navegador para compartirla.')}}catch(e){if((e as Error).name!=='AbortError')setNotice('No se pudo compartir. Inténtalo de nuevo.')}}}>↗ Compartir app</button><button className="round" aria-label="Reset" onClick={()=>setResetMode(true)}><Heart size={19}/></button></div></header><main>{tab==='Inicio'&&!page&&!resetMode&&!ziggyQuiet&&<div className="ziggy-intro"><div className="ziggy-fox" aria-label="Ziggy, el zorrito violeta con audífonos"><img src="./icon-512.png" alt="Ziggy, el zorrito violeta con audífonos"/></div><div className="ziggy-intro-copy"><span className="ziggy-kicker">ZIGGY ESTÁ AQUÍ</span><strong>Tu ritmo también cuenta.</strong><p>{active?'Si perdiste el hilo, podemos encontrarlo.':ziggyQuiet?'Aquí estaré cuando me llames.':'No necesitas tener todo claro para empezar.'}</p><button className="ziggy-talk" onClick={()=>setZiggyOpen(true)}>Hablar con Ziggy <ArrowRight size={15}/></button></div></div>}{ziggyOpen&&<section className="ziggy-dialog" aria-label="Acompañamiento de Ziggy"><div className="ziggy-dialog-head"><span>✦ Ziggy · acompañamiento</span><button onClick={()=>setZiggyOpen(false)} aria-label="Cerrar Ziggy">×</button></div><p>{ziggyText}</p><div className="ziggy-moods">{([['saturada','Me saturé'],['dispersa','Estoy dispersa'],['bloqueada','No puedo empezar'],['bien','Estoy bien']] as const).map(([v,label])=><button key={v} className={ziggyFeeling===v?'chosen':''} onClick={()=>setZiggyFeeling(v)}>{label}</button>)}</div><button className="ziggy-next" onClick={ziggyAction}>{ziggyFeeling==='saturada'?'Ir a Reset':ziggyFeeling==='dispersa'?'Guardar una chispa':ziggyFeeling==='bloqueada'?'Ir a Arranque':active?'Retomar actividad':'Ver Mi día'} <ArrowRight size={16}/></button><div className="ziggy-ai"><div className="ziggy-ai-title">✦ Conversa con Ziggy IA <span>Beta</span></div><p className="ziggy-ai-privacy">Escribe solo lo que quieras compartir. Tus mensajes se envían al servicio de IA para generar una respuesta. No incluyas datos sensibles.</p><div className="ziggy-memory"><label className="ziggy-memory-toggle"><input type="checkbox" checked={memoryEnabled} onChange={e=>setMemoryEnabled(e.target.checked)}/> Permitir que Ziggy use mis preferencias guardadas</label><p className="ziggy-ai-privacy">Opcional. Solo se envía a la IA el texto que tú guardes aquí. No se extraen tus tareas ni conversaciones automáticamente.</p><button type="button" className="ziggy-memory-edit" onClick={()=>setMemoryEditor(v=>!v)}>{memoryEditor?'Cerrar preferencias':'Editar lo que Ziggy puede recordar'}</button>{memoryEditor&&<div className="ziggy-memory-editor"><label>Mis preferencias para recibir ayuda<textarea rows={3} maxLength={500} placeholder="Ej.: Prefiero pasos breves y que me preguntes antes de sugerir horarios." value={memoryNote} onChange={e=>setMemoryNote(e.target.value)}/></label><div className="ziggy-ai-actions"><button type="button" onClick={()=>setMemoryEditor(false)}>Listo</button><button type="button" onClick={()=>{setMemoryNote('');localStorage.removeItem('zigzag-ai-memory-note');setMemoryEnabled(false)}}>Borrar preferencias</button></div><small>No escribas diagnósticos, contraseñas, direcciones ni datos de otras personas.</small></div>}</div><section className="ziggy-unblock" aria-label="Modo desbloqueo"><h3>¿Qué necesitas ahora?</h3><p>Elige lo que más se parezca a tu momento. Puedes cambiar de opción cuando quieras.</p><div className="ziggy-unblock-grid">{([['inicio','No sé cómo empezar'],['saturacion','Tengo demasiadas cosas'],['energia','Tengo poca energía'],['distraccion','Me distraje']] as const).map(([id,label])=><button type="button" key={id} aria-pressed={unblockMode===id} className={unblockMode===id?'selected':''} onClick={()=>setUnblockMode(unblockMode===id?null:id)}>{label}</button>)}</div>{unblockMode&&<div className="ziggy-unblock-detail"><p>{unblockMode==='inicio'?'Podemos buscar un primer movimiento de menos de dos minutos.':unblockMode==='saturacion'?'No hace falta resolverlo todo. Podemos elegir una sola cosa.':unblockMode==='energia'?'Podemos pensar una versión más liviana, o elegir descansar.': 'Podemos encontrar el punto donde quedaste y retomar sin empezar de cero.'}</p><label>¿Qué tienes en mente? (opcional)<input value={unblockTask} maxLength={180} onChange={e=>setUnblockTask(e.target.value)} placeholder="Ej.: responder un correo" /></label><button type="button" onClick={()=>{const prompts={inicio:'Me cuesta empezar. Ayúdame a elegir un primer movimiento muy pequeño, sin presionarme.',saturacion:'Tengo demasiadas cosas en la cabeza. Ayúdame a elegir solo una prioridad y dejar el resto para después.',energia:'Tengo poca energía. Ayúdame a encontrar una opción de mínimo esfuerzo o a reconocer si necesito descansar.',distraccion:'Me distraje y quiero retomar. Ayúdame a ubicar dónde quedé y elegir un siguiente paso sencillo.'};setAiInput(prompts[unblockMode]+(unblockTask.trim()?' Contexto: '+unblockTask.trim():''));setUnblockMode(null)}}>Preparar mensaje para Ziggy</button><small>Revisa el mensaje antes de enviarlo. También puedes usar las herramientas sin IA.</small></div>}</section><div className="ziggy-ai-history" aria-live="polite">{aiMessages.length===0?<p className="ziggy-ai-empty">Puedes contarme qué te cuesta empezar o pedirme que dividamos una tarea en pasos pequeños.</p>:aiMessages.map((m,i)=><p key={i} className={m.role==='user'?'ziggy-ai-user':'ziggy-ai-assistant'}><strong>{m.role==='user'?'Tú':'Ziggy'}</strong>{m.content}</p>)}{aiBusy&&<p className="ziggy-ai-empty">Ziggy está pensando…</p>}</div>{aiError&&<p className="ziggy-ai-error" role="alert">{aiError}</p>}<form className="ziggy-ai-form" onSubmit={e=>{e.preventDefault();void askZiggy()}}><textarea aria-label="Mensaje para Ziggy" maxLength={1200} rows={2} placeholder="¿Qué necesitas ahora?" value={aiInput} onChange={e=>setAiInput(e.target.value)}/><button type="submit" disabled={aiBusy||!aiInput.trim()}>{aiBusy?'Enviando…':'Enviar a Ziggy'}</button></form><div className="ziggy-ai-actions"><button type="button" onClick={makeSteps} disabled={aiBusy||!aiMessages.some(m=>m.role==='assistant')}>Preparar pasos para Mi Día</button><button type="button" onClick={()=>{aiAbort.current?.abort();setAiMessages([]);setAiError('');setAiBusy(false);setSuggestedSteps([]);setStepFeedback('')}}>Borrar conversación</button></div>
{suggestedSteps.length>0&&<div className="ziggy-step-planner"><h3>Elige tus próximos pasos</h3><p>Son sugerencias editables, no tareas obligatorias.</p>{suggestedSteps.map(step=><div className="ziggy-step-edit" key={step.id}><input type="checkbox" aria-label="Incluir paso" checked={step.selected} onChange={e=>setSuggestedSteps(xs=>xs.map(x=>x.id===step.id?{...x,selected:e.target.checked}:x))}/><input type="text" aria-label="Editar paso" maxLength={120} value={step.text} onChange={e=>setSuggestedSteps(xs=>xs.map(x=>x.id===step.id?{...x,text:e.target.value}:x))}/></div>)}<div className="ziggy-ai-actions"><button type="button" onClick={saveSteps}>Guardar elegidos en Mi Día</button><button type="button" onClick={()=>setSuggestedSteps([])}>Cancelar</button></div></div>}
{stepFeedback&&<p className="ziggy-step-feedback" role="status">{stepFeedback}</p>}<small>Ziggy es una herramienta de apoyo, no un servicio de emergencias ni reemplaza atención profesional. {aiEnabled?'IA conectada.':'La IA requiere conexión a internet.'}</small></div></section>}{resetMode?<><button className="back" onClick={()=>{setResetMode(false);setResetStep('choose')}}><ChevronLeft size={17}/> Volver sin cambiar nada</button><div className="reset-hero"><span className="eyebrow">RESET · A TU RITMO</span><h1>Tu pausa también tiene lugar.</h1><p>No hay que completar ningún ejercicio. Puedes salir cuando quieras.</p></div>{resetStep==='choose'?<div className="panel"><h3>¿Qué te vendría bien?</h3><button className="option" onClick={()=>{pref('lowStim',!data.prefs.lowStim);setNotice(data.prefs.lowStim?'Volviste a la vista habitual.':'Activaste una vista con menos estímulos.')}}><EyeOff size={18}/> {data.prefs.lowStim?'Volver a la vista habitual':'Reducir estímulos visuales'} <ArrowRight size={16}/></button><button className="option" onClick={()=>setResetStep('pause')}><Heart size={18}/> Hacer una pausa sin reloj <ArrowRight size={16}/></button><button className="option" onClick={()=>setResetStep('orient')}><Map size={18}/> Volver al presente suavemente <ArrowRight size={16}/></button><button className="option" onClick={()=>{setResetMode(false);goTab('Mi día')}}><CalendarDays size={18}/> Volver a Mi día <ArrowRight size={16}/></button></div>:resetStep==='pause'?<div className="reset-quiet"><div className="reset-orb" aria-hidden="true">✦</div><h2>Por ahora, nada que demostrar.</h2><p>Puedes quedarte aquí el tiempo que necesites. No hay cuenta regresiva.</p><button className="secondary" onClick={()=>setResetStep('choose')}>Elegir otra opción</button></div>:<div className="panel reset-orient"><h2>Volver, sin exigencias</h2><p>Si te sirve, mira a tu alrededor y elige una sola cosa que puedas notar: un color, una textura o un sonido.</p><p>No tienes que cerrar los ojos ni respirar de una manera específica.</p><button className="secondary" onClick={()=>setResetStep('choose')}>Volver a las opciones</button></div>}<p className="reset-foot">Reset es una herramienta de autocuidado, no una intervención de emergencia.</p></>:page==='task'?<><button className="back" onClick={()=>open('')}><ChevronLeft size={17}/> Volver</button><h1>{editing?'Editar actividad':'Nueva actividad'}</h1><label>Nombre<input value={name} onChange={e=>setName(e.target.value)} placeholder="¿Qué quieres hacer?"/></label><label>Fecha<input type="date" value={date} onChange={e=>setDate(e.target.value)}/></label><label>Hora (opcional)<input type="time" value={time} onChange={e=>setTime(e.target.value)}/></label><label>Duración aproximada en minutos<input type="number" min="5" max="480" value={duration} onChange={e=>setDuration(e.target.value)}/></label><label>Punto para retomar (opcional)<textarea value={resume} onChange={e=>setResume(e.target.value)} placeholder="¿Dónde lo dejaste?"/></label><button className="primary" onClick={addTask}><Save size={17}/> Guardar</button></>:page==='estimate'?<><button className="back" onClick={()=>open('')}><ChevronLeft size={17}/> Volver</button><h1>Tiempo Realista</h1><p>Una estimación es orientativa, no una promesa.</p><div className="panel"><h3>{tasks.find(t=>t.id===estimateId)?.name}</h3><strong className="big">{estimateVal} min</strong><input type="range" min="5" max="180" step="5" value={estimateVal} onChange={e=>setEstimateVal(+e.target.value)}/><p>No se iniciará un temporizador ni se reservará un horario.</p><button className="primary" onClick={saveEstimate}>Guardar estimación</button></div></>:page==='plan'?<><button className="back" onClick={()=>open('')}><ChevronLeft size={17}/> Volver</button><h1>Plan B</h1><p>Selecciona las tareas flexibles que quieres pasar al día siguiente. Los compromisos con hora no se moverán.</p><div className="panel">{flexible.length?flexible.map(t=><label className="check" key={t.id}><input type="checkbox" checked={planIds.includes(t.id)} onChange={e=>setPlanIds(v=>e.target.checked?[...v,t.id]:v.filter(x=>x!==t.id))}/>{t.name}</label>):<p>No hay tareas flexibles para mover.</p>}</div><div className="panel teal"><strong>Vista previa</strong><p>{planIds.length} tarea(s) pasarán al día siguiente.</p></div><button className="primary" disabled={!planIds.length} onClick={applyPlan}>Confirmar cambios</button></>:page==='radar'?<><button className="back" onClick={()=>open('')}><ChevronLeft size={17}/> Volver</button><h1>RADAR</h1><p>Los cruces se muestran para que tú decidas.</p>{conflicts.length?conflicts.map(([a,b],i)=><div className="panel warning" key={i}><strong><AlertCircle size={17}/> Cruce de horario</strong><p>{a.name}: {a.time}–{fmt(mins(a.time)+(a.duration||30))}</p><p>{b.name}: {b.time}–{fmt(mins(b.time)+(b.duration||30))}</p><button className="secondary" onClick={()=>{setConflictId(b.id);setConflictTime(b.time);open('resolve')}}>Revisar alternativas</button></div>):<div className="panel teal">No se detectaron horarios superpuestos para esta fecha.</div>}<button className="secondary" onClick={()=>{setEditing(null);setName('');setTime('');setDuration('30');open('task')}}><Plus size={16}/> Agregar compromiso</button></>:page==='resolve'?<><button className="back" onClick={()=>open('radar')}><ChevronLeft size={17}/> RADAR</button><h1>Revisar horario</h1><p>Elegir un horario nuevo es opcional. Nada cambiará hasta que confirmes.</p><div className="panel"><h3>{tasks.find(t=>t.id===conflictId)?.name}</h3><label>Nueva hora<input type="time" value={conflictTime} onChange={e=>setConflictTime(e.target.value)}/></label><button className="primary" onClick={()=>{if(!conflictTime)return;setUndo(tasks);update(conflictId,{time:conflictTime});open('radar');setNotice('Horario modificado. Puedes deshacerlo en Mi día.')}}>Confirmar cambio</button></div></>:page==='focusSession'?<><h1>Mi Foco</h1><div className="focus"><Target size={36}/><h2>{tasks.find(t=>t.id===focusId)?.name}</h2>{data.prefs.focus!=='untimed'&&<strong className="big">{fmt(Math.floor(focusSeconds/60))}:{String(focusSeconds%60).padStart(2,'0')}</strong>}<p>Tu ritmo. Sin puntuaciones.</p><section className="focus-smart" aria-label="Opciones de foco"><h3>¿Cuánto quieres intentar?</h3><div className="focus-smart-choices">{([ [0,'Sin límite'],[120,'2 minutos'],[300,'5 minutos'],[600,'10 minutos'] ] as const).map(([seconds,label])=><button type="button" key={seconds} aria-pressed={focusGoal===seconds} className={focusGoal===seconds?'selected':''} onClick={()=>{setFocusGoal(seconds);setFocusBreak(false)}}>{label}</button>)}</div>{focusGoal>0&&<p className="focus-smart-status" role="status">{focusSeconds>=focusGoal?'Llegaste al tiempo que elegiste. Puedes parar, continuar o descansar.':`Te quedan aproximadamente ${Math.max(0,Math.ceil((focusGoal-focusSeconds)/60))} minuto(s) de tu tiempo elegido.`}</p>}<div className="focus-guide"><button type="button" className="focus-guide-toggle" aria-expanded={focusGuide} onClick={()=>{setFocusGuide(v=>!v);setFocusGoal(300)}}>{focusGuide?'Ocultar guía de introducción':'Probar guía de 5 minutos para una introducción'}</button>{focusGuide&&<div className="focus-guide-steps"><p>Objetivo: ordenar ideas, no escribir una introducción perfecta.</p>{['Elegir la idea principal','Anotar dos ideas de apoyo','Decidir cuál idea podría ir primero'].map((label,i)=><label key={i}><input type="checkbox" checked={focusGuideChecks[i]} onChange={e=>setFocusGuideChecks(prev=>prev.map((v,j)=>i===j?e.target.checked:v))}/>{label}</label>)}<button type="button" onClick={()=>setFocusNote('Introducción: '+(['Idea principal','Dos ideas de apoyo','Orden inicial'].filter((_,i)=>focusGuideChecks[i]).join(', ')||'pendiente de organizar')+'. Próximo paso: retomar desde aquí.')}>Guardar mi punto de regreso</button><small>Las casillas son opcionales. No hay obligación de completarlas.</small></div>}</div><div className="focus-smart-actions"><button type="button" onClick={()=>{setFocusRunning(false);setFocusBreak(true);update(focusId,{status:'paused',resume:focusNote.trim()})}}>Necesito una pausa</button><button type="button" onClick={()=>{setAiInput(`Estoy trabajando en: ${tasks.find(t=>t.id===focusId)?.name||'una actividad'}. ${focusBreak?'Me detuve y quiero retomar con calma.':'Ayúdame a elegir un siguiente paso breve y una pausa realista.'} Mi punto de regreso es: ${focusNote.trim()||'todavía no lo definí'}. No cambies mis tareas automáticamente.`);setZiggyOpen(true)}}>Pedir ayuda a Ziggy</button></div>{focusBreak&&<p role="status">Tu pausa está bien. Cuando quieras, pulsa «Continuar» para retomar desde tu punto de regreso.</p>}</section><label className="focus-note">Mi punto de regreso<textarea value={focusNote} onChange={e=>setFocusNote(e.target.value)} placeholder="¿Dónde quiero continuar si me interrumpo?"/></label><button className="secondary" onClick={()=>{update(focusId,{resume:focusNote.trim()});setNotice('Punto de regreso guardado.')}}><Save size={17}/> Guardar mi punto</button><button className="primary" onClick={()=>{setFocusRunning(v=>!v);setFocusBreak(false);update(focusId,{status:focusRunning?'paused':'active'})}}>{focusRunning?<Pause size={18}/>:<Play size={18}/>} {focusRunning?'Pausar':'Continuar'}</button><button className="secondary" onClick={()=>{setFocusRunning(false);update(focusId,{status:'paused',resume:focusNote.trim()});open('');goTab('Inicio')}}>Guardar y salir</button><button className="secondary" onClick={()=>{setFocusRunning(false);update(focusId,{status:'done',resume:focusNote.trim()});open('');goTab('Inicio')}}>Terminar voluntariamente</button></div></>:page==='camino'?<><button className="back" onClick={()=>open('mapa')}><ChevronLeft size={17}/> Mi Mapa</button><span className="eyebrow dark">MI CAMINO · UNA ACTIVIDAD A LA VEZ</span><h1>Un camino, a tu ritmo.</h1><p>Empezar, concentrarte y volver están conectados. Puedes detenerte cuando quieras.</p>{!flowId?<div className="panel"><h3>Elige una actividad</h3>{tasks.filter(t=>t.status!=='done').map(t=><button className="option" key={t.id} onClick={()=>openFlow(t.id)}>{t.name}<ArrowRight size={16}/></button>)}{!tasks.some(t=>t.status!=='done')&&<p>No hay actividades pendientes. Puedes crear una desde Mi día.</p>}</div>:<div className="panel flow-journey"><span className="step-tag">1 · ARRANQUE → 2 · MI FOCO → 3 · VUELVE</span><h2>{tasks.find(t=>t.id===flowId)?.name||'Actividad'}</h2><p>¿Cuál es el siguiente paso pequeño? Puedes modificarlo cada vez que vuelvas.</p><label>Mi punto de partida<textarea value={flowStep} onChange={e=>setFlowStep(e.target.value)} placeholder="Por ejemplo: abrir el archivo y leer una línea"/></label><div className="starter-chips">{['Abrir lo necesario','Elegir una parte','Hacer una prueba pequeña'].map(x=><button key={x} onClick={()=>setFlowStep(x)}>{x}</button>)}</div><button className="primary" disabled={!flowStep.trim()} onClick={()=>{update(flowId,{resume:flowStep.trim(),status:'paused'});setNotice('Punto guardado. Lo encontrarás en Vuelve.')}}><Save size={17}/> Guardar mi punto</button><button className="primary" onClick={()=>{update(flowId,{resume:flowStep.trim()||tasks.find(t=>t.id===flowId)?.resume||'',status:'active'});startFocus(flowId)}}><Target size={17}/> Ir a Mi Foco</button><button className="secondary" onClick={()=>{update(flowId,{resume:flowStep.trim()||tasks.find(t=>t.id===flowId)?.resume||'',status:'paused'});open('vuelve')}}><RotateCcw size={17}/> Ir a Vuelve</button><button className="secondary" onClick={()=>{update(flowId,{status:'done'});setFlowId('');open('mapa');setNotice('Actividad completada.')}}><Check size={17}/> Marcar como realizada</button><button className="secondary" onClick={()=>{setFlowId('');setFlowStep('')}}>Elegir otra actividad</button></div>}<div className="gentle-tip"><span>✦ Ziggy</span><p>Lo que guardes aquí también estará disponible en Mi Foco y Vuelve. No hay que seguir un orden perfecto.</p></div></>:page==='arranque'?<><button className="back" onClick={()=>open('')}><ChevronLeft size={17}/> Volver</button><span className="eyebrow dark">ARRANQUE · SIN PRISA</span><h1>Un comienzo a tu manera.</h1><p>Elige algo que quieras empezar. No tienes que terminarlo ahora.</p>{!starterId?<div className="panel"><h3>¿Qué quieres empezar?</h3>{tasks.filter(t=>t.status!=='done').map(t=><button className="option" key={t.id} onClick={()=>{setStarterId(t.id);setStarterStep(t.resume||'')}}>{t.name}<ArrowRight size={16}/></button>)}{!tasks.some(t=>t.status!=='done')&&<p>Tu lista está vacía. Puedes crear una actividad, sin asignarle hora.</p>}<button className="secondary" onClick={()=>{setEditing(null);setName('');setTime('');open('task')}}><Plus size={16}/> Crear actividad</button></div>:<div className="panel starter"><span className="step-tag">PASO 1 DE 2 · ENCONTRAR UN INICIO</span><h3>{tasks.find(t=>t.id===starterId)?.name}</h3><p>¿Cuál sería una acción tan pequeña que resulte posible? Puedes escribirla o elegir una sugerencia.</p><div className="starter-chips">{(data.prefs.start==='prepare'?['Preparar el espacio','Dejar a mano lo necesario','Abrir el material']:['Abrir lo que necesito','Hacer solo dos minutos','Elegir la primera parte']).map(t=><button key={t} onClick={()=>setStarterStep(t)} className={starterStep===t?'chosen':''}>{t}</button>)}</div><label>Mi primer paso<textarea value={starterStep} onChange={e=>setStarterStep(e.target.value)} placeholder="Por ejemplo: abrir el documento"/></label><button className="primary" disabled={!starterStep.trim()} onClick={()=>{setData(d=>({...d,tasks:d.tasks.map(t=>t.id===starterId?{...t,status:'active',resume:starterStep.trim()}:t.status==='active'?{...t,status:'paused'}:t)}));setStarterId('');setStarterStep('');open('vuelve');setNotice('Primer paso guardado. Puedes retomarlo cuando quieras.')}}><Check size={17}/> Guardar y empezar a mi ritmo</button><button className="secondary" onClick={()=>{setStarterId('');setStarterStep('')}}>Elegir otra actividad</button></div>}<div className="gentle-tip"><span>✦ Ziggy</span><p>{data.prefs.start==='prepare'?'Preparar el entorno también es empezar.':data.prefs.start==='choose'?'No existe una única forma correcta de arrancar.':'Un paso pequeño es suficiente. No hay que demostrar nada.'}</p></div></>:page==='vuelve'?<><button className="back" onClick={()=>open('')}><ChevronLeft size={17}/> Volver</button><span className="eyebrow dark">VUELVE · SIN CULPA</span><h1>Tu hilo sigue aquí.</h1><p>No tienes que empezar desde cero ni explicar por qué te detuviste. Elige si quieres retomar, ajustar el punto o dejarlo para después.</p><div className="gentle-tip"><span>✦ Ziggy recuerda tu manera de empezar</span><p>{ziggyStartTip} {data.prefs.focus==='untimed'?'No necesitas usar un reloj.':'El tiempo será una opción, no una obligación.'}</p></div>{resumable.length?resumable.map(t=><div className="panel return-card" key={t.id}><span className="map-status">{t.status==='active'?'EN CURSO':t.status==='paused'?'EN PAUSA':'PUNTO GUARDADO'}</span><h3>{t.name}</h3><div className="return-point"><small>DONDE LO DEJÉ</small><p>{t.resume||'Todavía no guardaste un punto. Puedes elegir cómo volver.'}</p></div><div className="return-actions"><button className="primary" onClick={()=>startFocus(t.id)}><Play size={16}/> Retomar a mi ritmo</button><button className="secondary" onClick={()=>editTask(t)}>Cambiar mi punto</button><button className="secondary" onClick={()=>{update(t.id,{status:'paused'});setNotice('Aquí queda guardado. Puedes volver cuando quieras.')}}>Dejar para después</button></div></div>):<div className="panel return-empty"><h3>No hay hilos pendientes</h3><p>Cuando pauses una actividad o guardes un punto de regreso en Mi Foco, aparecerá aquí. No tienes que crear uno ahora.</p><button className="secondary" onClick={()=>open('mapa')}>Ver Mi Mapa</button></div>}</>:page==='chispas'?<><button className="back" onClick={()=>open('')}><ChevronLeft size={17}/> Volver</button><span className="eyebrow dark">CHISPAS</span><h1>Tu cabeza tiene espacio aquí.</h1><p>Guarda ideas, pendientes sueltos o preguntas. Nada se convierte en obligación.</p><div className="panel spark-composer"><h3>Capturar una chispa</h3><div className="chip-row">{([['idea','Idea'],['pendiente','Para después'],['pregunta','Pregunta'],['inspiracion','Inspiración']] as const).map(([id,label])=><button key={id} className={sparkCategory===id?'selected':''} onClick={()=>setSparkCategory(id)}>{label}</button>)}</div><textarea value={spark} onChange={e=>setSpark(e.target.value)} placeholder="Escríbela como salga. No tiene que estar ordenada…"/><button className="primary" disabled={!spark.trim()} onClick={()=>{setData(d=>({...d,sparks:[{id:uid(),text:spark.trim(),category:sparkCategory,created:today()},...d.sparks]}));setSpark('');setNotice('Chispa guardada. Puede esperar aquí.')}}><Plus size={17}/> Guardar chispa</button></div><label>Buscar entre mis chispas<input value={sparkSearch} onChange={e=>setSparkSearch(e.target.value)} placeholder="Una palabra que recuerdes…"/></label><h3>Mis chispas <em>{data.sparks.length}</em></h3>{data.sparks.filter(s=>s.text.toLocaleLowerCase().includes(sparkSearch.toLocaleLowerCase())).map(s=><div className="panel spark-card" key={s.id}><div><span className="spark-label">{({idea:'IDEA',pendiente:'PARA DESPUÉS',pregunta:'PREGUNTA',inspiracion:'INSPIRACIÓN'} as Record<string,string>)[s.category||'idea']}</span><p>{s.text}</p>{s.created&&<small>{s.created}</small>}</div><button className="icon" aria-label="Eliminar chispa" onClick={()=>{if(confirm('¿Eliminar esta chispa?'))setData(d=>({...d,sparks:d.sparks.filter(x=>x.id!==s.id)}))}}><Trash2 size={17}/></button></div>)}{!data.sparks.length&&<p className="muted">Este espacio está disponible cuando aparezca una idea.</p>}{data.sparks.length>0&&!data.sparks.some(s=>s.text.toLocaleLowerCase().includes(sparkSearch.toLocaleLowerCase()))&&<p className="muted">No hay chispas con esa palabra.</p>}</>:page==='mapa'?<><button className="flow-banner flow-banner-compact" onClick={()=>{setFlowId('');open('camino')}}><strong>✦ Empezar un camino con Ziggy</strong><small>Arranque, foco y regreso en una sola experiencia</small></button><button className="back" onClick={()=>open('')}><ChevronLeft size={17}/> Volver</button><span className="eyebrow dark">MI MAPA</span><h1>Todo lo que ronda, a la vista.</h1><p>No es una lista para terminar: es un lugar para encontrar y reorganizar tus actividades.</p><div className="map-overview"><div><strong>{tasks.filter(t=>t.status!=='done').length}</strong><small>Por hacer, sin prisa</small></div><div><strong>{tasks.filter(t=>t.status==='active'||t.status==='paused').length}</strong><small>En proceso</small></div><div><strong>{tasks.filter(t=>t.status==='done').length}</strong><small>Completadas</small></div></div><button className="primary" onClick={()=>{setEditing(null);setName('');setTime('');setResume('');open('task')}}><Plus size={17}/> Agregar actividad</button><div className="chip-row map-filters">{([['all','Todas'],['pending','Por hacer'],['active','En proceso'],['done','Hechas']] as const).map(([id,label])=><button key={id} className={mapFilter===id?'selected':''} onClick={()=>setMapFilter(id)}>{label}</button>)}</div>{tasks.filter(t=>mapFilter==='all'||(mapFilter==='active'?(t.status==='active'||t.status==='paused'):t.status===mapFilter)).map(t=><div className="panel map-card" key={t.id}><div className="map-card-main"><span className="map-status">{t.status==='done'?'HECHA':t.status==='paused'?'EN PAUSA':t.status==='active'?'EN CURSO':'POR HACER'}</span><strong>{t.name}</strong><small>{t.date} · {t.time||'Sin hora fija'} · {t.duration||30} min aproximados</small>{t.resume&&<p>↳ {t.resume}</p>}</div><div className="map-card-actions">{t.status!=='done'&&<div className="task-ziggy-tools" aria-label="Ayuda de Ziggy con esta actividad"><button className="mini" type="button" onClick={()=>askAboutTask(t,'iniciar')}>Empezar con Ziggy</button><button className="mini" type="button" onClick={()=>askAboutTask(t,'dividir')}>Dividir en pasos</button><button className="mini" type="button" onClick={()=>askAboutTask(t,'simplificar')}>Simplificar</button></div>}<button className="mini" onClick={()=>editTask(t)}>Editar</button>{t.status!=='done'?<button className="mini" onClick={()=>{update(t.id,{status:'done'});setNotice('Marcada como hecha.')}}><Check size={14}/> Hecha</button>:<button className="mini" onClick={()=>update(t.id,{status:'pending'})}>Reabrir</button>}<button className="icon" aria-label="Eliminar actividad" onClick={()=>{if(confirm('¿Eliminar esta actividad?'))setData(d=>({...d,tasks:d.tasks.filter(x=>x.id!==t.id)}))}}><Trash2 size={17}/></button></div></div>)}{!tasks.length&&<div className="panel"><p>Tu mapa está vacío. Puedes empezar por una sola cosa, o dejarlo así.</p></div>}{tasks.length>0&&!tasks.some(t=>mapFilter==='all'||(mapFilter==='active'?(t.status==='active'||t.status==='paused'):t.status===mapFilter))&&<p className="muted">No hay actividades en esta vista.</p>}</>:page==='manual-section'?<><button className="back" onClick={()=>open('')}><ChevronLeft size={17}/> Volver</button><h1>{sections.find(s=>s[0]===editing)?.[1]||'Tiempo Realista'}</h1>{configs[editing||'estimate']&&<div className="panel"><h3>{configs[editing||'estimate'].label}</h3>{configs[editing||'estimate'].options.map(([v,label])=><label className="radio" key={v}><input type="radio" checked={data.prefs[configs[editing||'estimate'].key]===v} onChange={()=>pref(configs[editing||'estimate'].key,v)}/>{label}</label>)}</div>}<p>Puedes cambiar esta preferencia cuando quieras.</p></>:page==='focusPick'?<><button className="back" onClick={()=>open('')}><ChevronLeft size={17}/> Volver</button><h1>Mi Foco</h1><p>Elige una actividad para retomar o empezar. El temporizador es opcional y puedes salir guardando tu punto.</p>{tasks.filter(t=>t.status!=='done').map(t=><button className="option" key={t.id} onClick={()=>startFocus(t.id)}>{t.name}<Play size={16}/></button>)}</>:page==='resources'?<><button className="back" onClick={()=>open('')}><ChevronLeft size={17}/> Volver</button><h1>Mis superrecursos</h1><p>Pequeñas cosas que a ti te funcionan.</p><input value={resource} onChange={e=>setResource(e.target.value)} placeholder="Algo que me ayuda…"/><button className="primary" disabled={!resource.trim()} onClick={()=>{setData(d=>({...d,resources:[...d.resources,resource.trim()]}));setResource('')}}>Guardar recurso</button>{data.resources.map((r,i)=><div className="panel item" key={i}>{r}<button className="icon" onClick={()=>setData(d=>({...d,resources:d.resources.filter((_,j)=>i!==j)}))}><Trash2 size={17}/></button></div>)}</>:tab==='Inicio'?<><section className="hero"><div className="hero-orbit" aria-hidden="true"><span>✦</span><span>✳</span><span>✦</span></div><span className="eyebrow">TU MENTE · TU RITMO · TU CAMINO</span><h1>Hoy, a tu manera.</h1><p>¿Qué necesitas ahora? No hay una forma correcta de empezar.</p></section><section className="home-pulse" aria-label="Tu día de un vistazo"><div><span className="pulse-kicker">TU DÍA, SIN PRESIÓN</span><strong>{tasks.filter(t=>t.date===today()&&t.status==='done').length} <small>de {tasks.filter(t=>t.date===today()).length} actividades realizadas</small></strong><div className="pulse-track" role="progressbar" aria-valuemin={0} aria-valuemax={tasks.filter(t=>t.date===today()).length||1} aria-valuenow={tasks.filter(t=>t.date===today()&&t.status==='done').length} aria-label="Actividades completadas hoy"><span style={{width:`${tasks.filter(t=>t.date===today()).length?100*tasks.filter(t=>t.date===today()&&t.status==='done').length/tasks.filter(t=>t.date===today()).length:0}%`}}/></div></div><button onClick={()=>goTab('Mi día')} aria-label="Abrir Mi día">Ver mi día <ArrowRight size={15}/></button></section>{active&&<button className="resume" onClick={()=>open('vuelve')}><RotateCcw size={18}/> Tu último punto sigue aquí <ArrowRight size={16}/></button>}<button className="flow-banner" onClick={()=>{setFlowId('');open('camino')}}><span>✦ TU CAMINO CON ZIGGY</span><strong>De una idea a una acción, sin perder el hilo</strong><small>Arranque → Mi Foco → Vuelve</small><span className="flow-arrow">Comenzar <ArrowRight size={16}/></span></button><div className="tool-heading"><span>ELIGE TU CAMINO</span><span>6 herramientas, cero exigencias</span></div><div className="tiles">{[{id:'arranque',title:'Empezar',sub:'No sé por dónde',icon:<Rocket/>},{id:'focus',title:'Concentrarme',sub:'Quiero mantener el hilo',icon:<Target/>},{id:'mapa',title:'Organizarme',sub:'Tengo mil cosas',icon:<Map/>},{id:'reset',title:'Regularme',sub:'Necesito bajar',icon:<Heart/>},{id:'vuelve',title:'Retomar',sub:'Perdí el hilo',icon:<RotateCcw/>},{id:'chispas',title:'Mis ideas',sub:'No quiero olvidarlas',icon:<Lightbulb/>}].map(t=><button className="tile" key={t.id} onClick={()=>t.id==='reset'?setResetMode(true):t.id==='focus'?(tasks.some(x=>x.status!=='done')?open('focusPick'):open('mapa')):open(t.id)}>{t.icon}<strong>{t.title}</strong><small>{t.sub}</small></button>)}</div></>:page==='focusPick'?<><h1>Mi Foco</h1><button className="secondary" onClick={()=>{setFlowId('');open('camino')}}>✦ Usar el camino guiado</button><p>Elige una actividad para retomar o empezar. El temporizador es opcional y puedes salir guardando tu punto.</p>{tasks.filter(t=>t.status!=='done').map(t=><button className="option" key={t.id} onClick={()=>startFocus(t.id)}>{t.name}<Play size={16}/></button>)}</>:tab==='Mi día'?<><section className="hero"><span className="eyebrow">MI DÍA</span><h1>El tiempo, a tu manera.</h1><p>No tienes que llenar cada espacio.</p></section><div className="date-navigator"><button aria-label="Día anterior" onClick={()=>setDate(shiftDate(date,-1))}>‹</button><label>Fecha<input type="date" value={date} onChange={e=>setDate(e.target.value)}/></label><button aria-label="Día siguiente" onClick={()=>setDate(shiftDate(date,1))}>›</button><button className="today-button" onClick={()=>setDate(today())}>Hoy</button></div><div className="day-summary"><div><strong>{allToday.length}</strong><span>actividades</span></div><div><strong>{completedToday.length}</strong><span>completadas</span></div><div><strong>{day.length}</strong><span>por hacer</span></div></div><div className="segmented"><button className={view==='cards'?'selected':''} onClick={()=>setView('cards')}>Tarjetas</button><button className={view==='timeline'?'selected':''} onClick={()=>setView('timeline')}>Línea de tiempo</button></div>{conflicts.length>0&&<button className="warning option" onClick={()=>open('radar')}><AlertCircle size={18}/> {conflicts.length} cruce(s) de horario <ArrowRight size={16}/></button>}{view==='cards'?<><h3>Lo próximo <em>{fixed.length}</em></h3>{fixed.length===0&&<p className="muted">No tienes compromisos con hora. Puedes dejar el día abierto.</p>}{(expand?fixed:fixed.slice(0,3)).map(t=><div className="task" key={t.id}><button className="task-main" onClick={()=>editTask(t)}><span className="timechip">{t.time}</span><span><strong>{t.name}</strong><small>{t.duration||30} min · hasta {fmt(mins(t.time)+(t.duration||30))}</small></span><ArrowRight size={16}/></button><button className="task-complete" aria-label={`Completar ${t.name}`} onClick={()=>update(t.id,{status:'done'})}><Check size={17}/></button></div>)}<h3>Lo que estoy haciendo</h3>{active?<button className="task" onClick={()=>open('vuelve')}><RotateCcw size={18}/><span><strong>{active.name}</strong><small>{active.resume||'Punto guardado'}</small></span></button>:<p className="muted">No hay una actividad activa.</p>}<h3>Lo que puede esperar <em>{flexible.length}</em></h3>{flexible.length===0&&<p className="muted">No hay actividades flexibles pendientes para esta fecha.</p>}{(expand?flexible:flexible.slice(0,3)).map(t=><div className="task" key={t.id}><Lightbulb size={18}/><span><strong>{t.name}</strong><small>{t.duration?`${t.duration} min estimados`:'Sin duración estimada'}</small></span><div className="task-actions"><button className="mini" onClick={()=>{setEstimateId(t.id);setEstimateVal(t.duration||30);open('estimate')}}>Estimar</button><button className="task-complete" aria-label={`Completar ${t.name}`} onClick={()=>update(t.id,{status:'done'})}><Check size={17}/></button></div></div>)}{completedToday.length>0&&<><h3>Ya hice <em>{completedToday.length}</em></h3>{completedToday.map(t=><div className="task completed" key={t.id}><Check size={18}/><span><strong>{t.name}</strong><small>Completada · puedes recuperarla</small></span><button className="mini" onClick={()=>update(t.id,{status:'pending'})}>Reabrir</button></div>)}</>}{(fixed.length>3||flexible.length>3)&&<button className="secondary" onClick={()=>setExpand(v=>!v)}>{expand?'Mostrar menos':'Ver todos'}</button>}</>:<><h3>Línea de tiempo proporcional</h3><div className="timeline"><div className="axis">{Array.from({length:13},(_,i)=><div key={i} style={{height:60}}>{fmt(480+i*60)}</div>)}</div><div className="track" style={{height:720}}>{Array.from({length:13},(_,i)=><div className="line" style={{top:i*60}} key={i}/>)}{fixed.filter(t=>mins(t.time)+(t.duration||30)>480&&mins(t.time)<1200).map(t=>{const overlapping=fixed.some(x=>x.id!==t.id&&mins(t.time)<mins(x.time)+(x.duration||30)&&mins(x.time)<mins(t.time)+(t.duration||30));return <button key={t.id} className={overlapping?'block conflict':'block'} style={{top:Math.max(0,mins(t.time)-480),height:Math.max(24,Math.min(t.duration||30,1200-mins(t.time))),width:overlapping?'48%':'96%',left:overlapping?(fixed.findIndex(x=>x.id===t.id)%2?'51%':'1%'):'2%'}} onClick={()=>editTask(t)}><strong>{t.name}</strong><small>{t.time} · {t.duration||30} min</small></button>})}</div></div><p className="muted">La escala es de 1 píxel por minuto, entre 08:00 y 20:00. Los bloques muy breves tienen un tamaño táctil mínimo.</p></>}<div className="actions"><button className="secondary" onClick={()=>{setEditing(null);setName('');setTime('');open('task')}}><Plus size={16}/> Agregar</button><button className="secondary" onClick={()=>open('radar')}><AlertCircle size={16}/> RADAR</button><button className="primary" onClick={startPlan}>Plan B</button></div>{undo&&<button className="secondary" onClick={()=>{setData(d=>({...d,tasks:undo}));setUndo(null);setNotice('Último cambio deshecho.')}}><Undo2 size={17}/> Deshacer último cambio</button>}</>:tab==='Mi Manual'?<><section className="hero"><span className="eyebrow">MI MANUAL</span><h1>Así me funciona mejor.</h1><p>No tienes que completarlo todo.</p></section><div className="tiles">{sections.map(([id,title])=><button className="tile" key={id} onClick={()=>{if(id==='resources')open('resources');else{setEditing(id);open('manual-section')}}}>{renderIcon(id)}<strong>{title}</strong><small>Lo que me sirve</small></button>)}</div><button className="option" onClick={()=>{setEditing('estimate');open('manual-section')}}><Clock size={18}/> Tiempo Realista <ArrowRight size={17}/></button><label className="check panel"><input type="checkbox" checked={data.prefs.lowStim} onChange={e=>pref('lowStim',e.target.checked)}/> Reducir estímulos visuales</label></>:<><section className="hero"><span className="eyebrow">MI ESPACIO</span><h1>Un lugar para ti.</h1><p>Tu información permanece en este dispositivo.</p></section><button className="option" onClick={()=>open('chispas')}><Lightbulb size={18}/> Mis ideas ({data.sparks.length}) <ArrowRight size={17}/></button><button className="option" onClick={()=>open('vuelve')}><RotateCcw size={18}/> ¿Dónde lo dejé? <ArrowRight size={17}/></button><button className="option" onClick={()=>open('resources')}><BookOpen size={18}/> Mis superrecursos <ArrowRight size={17}/></button><div className="panel"><h3>Privacidad</h3><p>Esta versión guarda datos en el navegador. No hay cuenta, sincronización ni notificaciones reales.</p><button className="secondary" onClick={()=>{if(confirm('¿Eliminar todos los datos locales de ZIGZAG?')){setData(initial);localStorage.removeItem('zigzag-ai-memory-note');localStorage.removeItem('zigzag-ai-memory-enabled');setMemoryNote('');setMemoryEnabled(false);setAiMessages([]);setNotice('Datos locales eliminados.')}}}>Borrar mis datos</button></div></>}{notice&&<div className="toast" role="status">{notice}<button aria-label="Cerrar" onClick={()=>setNotice('')}>×</button></div>}</main><button className="ziggy-fab" aria-label="Abrir acompañamiento de Ziggy" onClick={()=>{setZiggyOpen(v=>!v);setResetMode(false)}}><span>✦</span><span>Ziggy</span></button><nav>{[{id:'Inicio',icon:<House/>},{id:'Mi día',icon:<CalendarDays/>},{id:'Mi Manual',icon:<BookOpen/>},{id:'Mi espacio',icon:<UserRound/>}].map(t=><button key={t.id} className={tab===t.id?'active':''} onClick={()=>goTab(t.id)}>{t.icon}<span>{t.id}</span></button>)}</nav></div>}
if('serviceWorker' in navigator){window.addEventListener('load',()=>{navigator.serviceWorker.register('/sw.js').catch(()=>{});});}

function Welcome({onFinish}:{onFinish:()=>void}){
 const [step,setStep]=useState(0);
 const [start,setStart]=useState('tiny');
 const [focus,setFocus]=useState('untimed');
 const [support,setSupport]=useState('balanced');
 const [lowStim,setLowStim]=useState(false);
 const steps=[
  {tag:'HOLA, SOY ZIGGY',title:'Tu mente. Tu ritmo. Tu camino.',desc:'No necesitas adaptarte a una agenda rígida. ZIGZAG puede adaptarse a ti.'},
  {tag:'A TU MANERA',title:'¿Qué te ayuda a comenzar?',desc:'Puedes cambiar esta respuesta cuando quieras.',choices:[['tiny','Un paso pequeño'],['prepare','Preparar el espacio'],['choose','Mirar opciones primero']],value:start,set:setStart},
  {tag:'SIN PRESIÓN',title:'¿Cómo prefieres concentrarte?',desc:'El reloj es opcional, no una obligación.',choices:[['untimed','Sin temporizador'],['visible','Ver tiempo transcurrido'],['sessions','Elegir sesiones']],value:focus,set:setFocus},
  {tag:'TU ESPACIO',title:'¿Cuánta presencia quieres de Ziggy?',desc:'Siempre puedes llamarme desde el botón de la esquina.',choices:[['minimal','Solo cuando me necesites'],['balanced','Equilibrada'],['active','Sugerencias discretas']],value:support,set:setSupport},
  {tag:'LISTO PARA EMPEZAR',title:'No tienes que hacerlo todo hoy.',desc:'Puedes comenzar con una sola cosa, explorar o simplemente mirar.'}
 ];
 const current=steps[step];
 const finish=()=>{
  try{const existing=JSON.parse(localStorage.getItem('zigzag-v1')||'{}');const prefs={...initial.prefs,...(existing.prefs||{}),start,focus,support,lowStim};localStorage.setItem('zigzag-v1',JSON.stringify({...initial,...existing,prefs}));localStorage.setItem('zigzag-welcome-v1','done')}catch{localStorage.setItem('zigzag-welcome-v1','done')}
  onFinish();
 };
 return <div className={'welcome-screen'+(lowStim?' welcome-quiet':'')}><div className="welcome-card">
  <div className="welcome-top"><div className="welcome-mark" aria-hidden="true">✦</div><span>ZIGZAG</span><span className="welcome-counter">{step+1} / {steps.length}</span></div>
  <div className="welcome-progress" aria-label={'Paso '+(step+1)+' de '+steps.length}><span style={{width:((step+1)/steps.length*100)+'%'}}/></div>
  <div className="welcome-illustration" aria-hidden="true"><span className="welcome-ziggy">✦</span><span className="welcome-orbit orbit-one"/><span className="welcome-orbit orbit-two"/></div>
  <span className="welcome-eyebrow">{current.tag}</span><h1>{current.title}</h1><p>{current.desc}</p>
  {'choices' in current&&current.choices&&<div className="welcome-choices" role="group" aria-label={current.title}>{current.choices.map(([value,label])=><button key={value} type="button" aria-pressed={current.value===value} className={current.value===value?'chosen':''} onClick={()=>current.set?.(value)}>{label}<span>{current.value===value?'✓':'+'}</span></button>)}</div>}
  {step===3&&<label className="welcome-check"><input type="checkbox" checked={lowStim} onChange={e=>setLowStim(e.target.checked)}/> Prefiero una pantalla con menos estímulos</label>}
  <div className="welcome-actions">{step>0&&<button className="welcome-back" onClick={()=>setStep(x=>x-1)}>Atrás</button>}<button className="welcome-next" onClick={()=>step===steps.length-1?finish():setStep(x=>x+1)}>{step===steps.length-1?'Entrar a ZIGZAG':'Continuar'} <ArrowRight size={18}/></button></div>
  <button className="welcome-skip" onClick={finish}>Configurar después</button>
  <small>Sin cuentas ni diagnósticos. Tus elecciones se guardan en este dispositivo.</small>
 </div></div>
}
function Root(){
 const [ready,setReady]=useState(()=>localStorage.getItem('zigzag-welcome-v1')==='done');
 const [audioMode,setAudioMode]=useState(()=>localStorage.getItem('zigzag-voice-mode')==='audio');
 const [speaking,setSpeaking]=useState(false);
 const [voices,setVoices]=useState<SpeechSynthesisVoice[]>([]);
 const [voiceMessage,setVoiceMessage]=useState('');
 const [selectedText,setSelectedText]=useState('');
 const [voiceSpeed,setVoiceSpeed]=useState(()=>Number(localStorage.getItem('zigzag-voice-speed')||'0.93'));
 const [guideKind,setGuideKind]=useState('');
 const [guideStep,setGuideStep]=useState(0);
 const [guideNote,setGuideNote]=useState('');
 const [backupStatus,setBackupStatus]=useState('');
 const exportBackup=()=>{
  const payload={format:'zigzag-backup',version:1,createdAt:new Date().toISOString(),data:JSON.parse(localStorage.getItem('zigzag-v1')||'{}'),welcome:localStorage.getItem('zigzag-welcome-v1'),voiceMode:localStorage.getItem('zigzag-voice-mode'),voiceSpeed:localStorage.getItem('zigzag-voice-speed'),guideNotes:JSON.parse(localStorage.getItem('zigzag-guide-notes')||'[]')};
  const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});
  const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='zigzag-respaldo-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);setBackupStatus('Respaldo preparado para descargar.');
 };
 const importBackup=async(file:File)=>{
  try{
   if(file.size>2_000_000)throw new Error('El archivo es demasiado grande.');
   const raw=JSON.parse(await file.text());
   if(raw?.format!=='zigzag-backup'||raw.version!==1||!raw.data||!Array.isArray(raw.data.tasks)||!Array.isArray(raw.data.sparks)||!raw.data.prefs||typeof raw.data.prefs!=='object')throw new Error('Este archivo no es un respaldo válido de ZIGZAG.');
   if(!window.confirm('¿Restaurar este respaldo? Reemplazará tus actividades e ideas actuales.'))return;
   localStorage.setItem('zigzag-v1',JSON.stringify(raw.data));
   if(Array.isArray(raw.guideNotes))localStorage.setItem('zigzag-guide-notes',JSON.stringify(raw.guideNotes));
   if(raw.voiceMode==='audio'||raw.voiceMode==='text')localStorage.setItem('zigzag-voice-mode',raw.voiceMode);
   if(['0.75','0.93','1.1'].includes(raw.voiceSpeed))localStorage.setItem('zigzag-voice-speed',raw.voiceSpeed);
   localStorage.setItem('zigzag-welcome-v1','done');window.location.reload();
  }catch(e){setBackupStatus(e instanceof Error?e.message:'No se pudo leer el respaldo.');}
 };

 const guides:Record<string,{title:string;steps:string[]}>= {
  start:{title:'Empezar a mi manera',steps:['Elige una sola cosa que te gustaría comenzar. No necesitas resolverla completa.','Piensa en una acción tan pequeña que puedas hacerla ahora. Puedes escribirla aquí.','Prueba ese primer movimiento. Si no resulta, puedes cambiarlo sin empezar de cero.','Reconoce lo que sí hiciste. Puedes continuar o dejar un punto de regreso.']},
  focus:{title:'Encontrar mi foco',steps:['Elige qué quieres tener frente a ti. Lo demás puede esperar.','Prepara lo necesario y aparta una distracción, si te ayuda.','Comienza a tu ritmo. No necesitas un temporizador para que cuente.','Antes de salir, anota dónde quedaste para volver más fácilmente.']},
  reset:{title:'Una pausa posible',steps:['Nota cómo estás ahora, sin intentar cambiarlo de inmediato.','Busca una sensación de apoyo: pies en el suelo, espalda en el respaldo o un objeto cercano.','Si te acomoda, baja un estímulo: luz, sonido o cantidad de cosas a la vista.','Decide si quieres descansar un poco más, retomar algo o terminar aquí.']},
  return:{title:'Volver sin partir de cero',steps:['Recuerda cuál era la actividad, sin exigirte retomarla todavía.','Busca tu última nota o el punto donde quedaste.','Elige un gesto pequeño para recuperar el hilo.','Puedes continuar, guardar otro punto de regreso o dejarlo para después.']}
 };
 const guide=guides[guideKind];
 const openGuide=(kind:string)=>{setGuideKind(kind);setGuideStep(0);setGuideNote('');if('speechSynthesis' in window)window.speechSynthesis.cancel();setSpeaking(false)};
 const closeGuide=()=>{setGuideKind('');if('speechSynthesis' in window)window.speechSynthesis.cancel();setSpeaking(false)};

 useEffect(()=>localStorage.setItem('zigzag-voice-speed',String(voiceSpeed)),[voiceSpeed]);
 useEffect(()=>{
  if(!('speechSynthesis' in window))return;
  const refresh=()=>setVoices(window.speechSynthesis.getVoices());
  refresh();window.speechSynthesis.addEventListener('voiceschanged',refresh);
  return()=>{window.speechSynthesis.cancel();window.speechSynthesis.removeEventListener('voiceschanged',refresh)};
 },[]);
 useEffect(()=>{localStorage.setItem('zigzag-voice-mode',audioMode?'audio':'text');if(!audioMode&&'speechSynthesis' in window){window.speechSynthesis.cancel();setSpeaking(false)}},[audioMode]);
 const chileVoice=voices.find(v=>v.lang.toLowerCase().replace('_','-')==='es-cl');
 const spanishVoice=voices.find(v=>v.lang.toLowerCase().startsWith('es'));
 const chosenVoice=chileVoice||spanishVoice;
 const speakText=(text:string)=>{
  if(!('speechSynthesis' in window)){setVoiceMessage('Este dispositivo no permite lectura de voz. Puedes seguir leyendo el texto.');return}
  window.speechSynthesis.cancel();setSpeaking(false);
  const clean=text.replace(/\s+/g,' ').trim();
  if(!clean){setVoiceMessage('Selecciona un texto para escucharlo.');return}
  const utterance=new SpeechSynthesisUtterance(clean.slice(0,7000));
  utterance.lang=chosenVoice?.lang||'es-CL';
  if(chosenVoice)utterance.voice=chosenVoice;
  utterance.rate=voiceSpeed;utterance.pitch=1;
  utterance.onstart=()=>setSpeaking(true);
  utterance.onend=()=>setSpeaking(false);
  utterance.onerror=()=>{setSpeaking(false);setVoiceMessage('No se pudo reproducir el audio en este dispositivo.')};
  setVoiceMessage(chileVoice?'Usando voz chilena.':spanishVoice?'No hay voz chilena instalada: usando otra voz en español.':'La voz dependerá de la configuración de tu dispositivo.');
  window.speechSynthesis.speak(utterance);
 };
 const chooseFragment=(event:React.MouseEvent<HTMLDivElement>)=>{
  if(!audioMode)return;
  const target=event.target as HTMLElement;
  if(target.closest('button,a,input,textarea,select,label,[role="button"],.voice-access'))return;
  const element=target.closest('p,h1,h2,h3,h4,li,blockquote,.task-name,.welcome-eyebrow') as HTMLElement|null;
  if(!element)return;
  const text=(element.innerText||element.textContent||'').replace(/\s+/g,' ').trim();
  if(text&&text.length>2)setSelectedText(text.slice(0,1200));
 };
 const readScreen=()=>{
  const area=document.querySelector(ready?'main':'.welcome-card') as HTMLElement|null;
  if(!area)return;
  const clone=area.cloneNode(true) as HTMLElement;
  clone.querySelectorAll('button,nav,input,textarea,select,small,.welcome-progress,.welcome-illustration,.toast').forEach(el=>el.remove());
  speakText(clone.innerText||clone.textContent||'');
 };
 return <><div className="voice-access" role="group" aria-label="Preferencia de lectura">
  <span className="voice-access-label">Contenido</span>
  <button type="button" className={!audioMode?'voice-selected':''} aria-pressed={!audioMode} onClick={()=>setAudioMode(false)}>Escrito</button>
  <button type="button" className={audioMode?'voice-selected':''} aria-pressed={audioMode} onClick={()=>setAudioMode(true)}><Volume2 size={15}/> Audio</button>
  {audioMode&&<button type="button" className="voice-play" onClick={speaking?()=>{window.speechSynthesis.cancel();setSpeaking(false)}:readScreen}>{speaking?<><Square size={14}/> Detener</>:<><Play size={14}/> Escuchar pantalla</>}</button>}
 {audioMode&&<label className="voice-speed">Velocidad <select aria-label="Velocidad de voz" value={voiceSpeed} onChange={e=>setVoiceSpeed(Number(e.target.value))}><option value="0.75">Lenta</option><option value="0.93">Normal</option><option value="1.1">Rápida</option></select></label>}
 </div>{audioMode&&selectedText&&<div className="voice-fragment"><span>{selectedText.slice(0,95)}{selectedText.length>95?'…':''}</span><button type="button" onClick={()=>speakText(selectedText)}><Volume2 size={15}/> Escuchar fragmento</button><button type="button" aria-label="Cerrar fragmento" onClick={()=>setSelectedText('')}>×</button></div>}{audioMode&&voiceMessage&&<div className="voice-message" role="status">{voiceMessage}</div>}
 {ready&&<details className="zigzag-backup"><summary>Mis datos · respaldo</summary><div><p>Guarda una copia de tus actividades, ideas y preferencias. El archivo queda bajo tu control.</p><button type="button" onClick={exportBackup}>Descargar respaldo</button><label>Restaurar respaldo <input type="file" accept="application/json,.json" onChange={e=>{const f=e.target.files?.[0];if(f)void importBackup(f);e.target.value=''}}/></label>{backupStatus&&<p role="status">{backupStatus}</p>}</div></details>}
 {ready&&<div className="ziggy-guide-entry" aria-label="Acompañamiento paso a paso"><button type="button" onClick={()=>openGuide('start')}>✦ Acompáñame paso a paso</button></div>}
 {ready&&guide&&<div className="ziggy-guide-backdrop" role="presentation"><section className="ziggy-guide" role="dialog" aria-modal="true" aria-labelledby="ziggy-guide-title">
  <div className="ziggy-guide-top"><span aria-hidden="true" className="ziggy-guide-avatar">✦</span><span>ZIGGY TE ACOMPAÑA</span><button type="button" onClick={closeGuide} aria-label="Cerrar acompañamiento">×</button></div>
  <h2 id="ziggy-guide-title">{guide.title}</h2>
  <div className="ziggy-guide-kinds" role="group" aria-label="Elegir acompañamiento">{[['start','Empezar'],['focus','Foco'],['reset','Reset'],['return','Volver']].map(([key,label])=><button type="button" key={key} aria-pressed={guideKind===key} className={guideKind===key?'current':''} onClick={()=>openGuide(key)}>{label}</button>)}</div>
  <div className="ziggy-guide-progress"><span>Paso {guideStep+1} de {guide.steps.length}</span><div className="ziggy-guide-track"><div style={{width:((guideStep+1)/guide.steps.length*100)+'%'}}/></div></div>
  <div className="ziggy-guide-message"><p>{guide.steps[guideStep]}</p>{audioMode&&<button type="button" onClick={()=>speakText(guide.steps[guideStep])}><Volume2 size={17}/> Escuchar este paso</button>}</div>
  {(guideKind==='start'&&guideStep===1||guideKind==='focus'&&guideStep===3||guideKind==='return'&&guideStep===1)&&<label className="ziggy-guide-note">Mi nota (opcional)<textarea value={guideNote} onChange={e=>setGuideNote(e.target.value)} placeholder="Escríbelo a tu manera…" rows={2}/></label>}
  <div className="ziggy-guide-actions"><button type="button" onClick={()=>setGuideStep(n=>Math.max(0,n-1))} disabled={guideStep===0}>Anterior</button><button type="button" className="ziggy-guide-primary" onClick={()=>{if(guideStep===guide.steps.length-1){if(guideNote.trim()){let stored:Array<{kind:string;text:string;date:string}>=[];try{const parsed=JSON.parse(localStorage.getItem('zigzag-guide-notes')||'[]');if(Array.isArray(parsed))stored=parsed}catch{}localStorage.setItem('zigzag-guide-notes',JSON.stringify([{kind:guideKind,text:guideNote.trim(),date:new Date().toISOString()},...stored].slice(0,30)))}closeGuide()}else{setGuideStep(n=>n+1);if('speechSynthesis' in window)window.speechSynthesis.cancel();setSpeaking(false)}}}>{guideStep===guide.steps.length-1?'Terminar a mi ritmo':'Siguiente paso'}</button></div>
  <button type="button" className="ziggy-guide-leave" onClick={closeGuide}>Por ahora, prefiero parar</button>
  <small>Sin cuentas regresivas. Puedes salir cuando quieras. Las notas se guardan solo en este dispositivo.</small>
 </section></div>}
 <div onClickCapture={chooseFragment}>{ready?<App/>:<Welcome onFinish={()=>setReady(true)}/>}</div></>;
}
createRoot(document.getElementById('root')!).render(<Root/>);
